findings.codeql_raw_query:
/**
 * @name Unsafe pickle deserialization dataflow
 * @description Tracing data flow from remote sources to pickle operations
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-pickle-dataflow
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PickleConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleFlow = TaintTracking::Global<PickleConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe deserialization of $@.", source.getNode(), "user input"
